/** QA import-path adaptation of frozen candidate route fd9b1115; source equality is verified by test. */
import {m71Uuid} from '../../packages/neuvetra-database/src/m71-validation'
import {M78ValidationError,parseM78Json,validateM78ProcessSave,validateM78InventorySave,validateM78Review,validateM78Report,m78CanonicalJson} from '../../packages/neuvetra-database/src/m78-validation'
import type {M78Authorities,M78Family,M78Policy,M78Register,M78VersionEnvelope,M78Report,M78ProcessSaveInput,M78InventorySaveInput,M78ReviewInput,M78Review,M78ReportInput} from '../../packages/neuvetra-database/src/m78-contract'
import {extractBearerToken,type AuthenticatedUser} from '../../apps/site-api/src/lib/auth'
export interface M78RouteDatabase {
 hasStagingAccess?:(userId:string)=>Promise<boolean>
 canManageWorkspace:(userId:string,companyId:string)=>Promise<boolean>
 findScope1:(userId:string,companyId:string,a:M78Authorities,policy:M78Policy|null)=>Promise<M78Register|null>
 findScope1Version:(userId:string,companyId:string,streamId:string,versionId:string,a:M78Authorities,policy:M78Policy|null)=>Promise<M78VersionEnvelope|null>
 findScope1Report:(userId:string,companyId:string,streamId:string,reportId:string,a:M78Authorities,policy:M78Policy|null)=>Promise<M78Report|null>
 saveProcessScreen:(userId:string,companyId:string,streamId:string|null,input:M78ProcessSaveInput,a:M78Authorities,policy:M78Policy|null)=>Promise<M78VersionEnvelope>
 saveScope1Inventory:(userId:string,companyId:string,streamId:string|null,input:M78InventorySaveInput,a:M78Authorities,policy:M78Policy|null)=>Promise<M78VersionEnvelope>
 reviewScope1Version:(userId:string,companyId:string,streamId:string,family:M78Family,input:M78ReviewInput,a:M78Authorities,policy:M78Policy|null)=>Promise<M78Review>
 createScope1Report:(userId:string,companyId:string,streamId:string,family:M78Family,input:M78ReportInput,a:M78Authorities,policy:M78Policy|null)=>Promise<M78Report>
}
export function createM78Routes(deps:{database:M78RouteDatabase;validateUser:(token:string)=>Promise<AuthenticatedUser|null>;origin:string;authorities:M78Authorities;policy?:M78Policy|null}){return async(request:Request):Promise<Response>=>{const respond=(status:number,body:unknown)=>Response.json(body,{status,headers:{'cache-control':'no-store'}}),match=/^\/workspace\/([^/]+)\/(process-screen|scope1-inventory)(?:\/([^/]+)\/(versions|reviews|reports|statements)(?:\/([^/]+)(?:\/(inventory-export|download|snapshot|proof))?)?)?$/.exec(new URL(request.url).pathname);if(!match||!m71Uuid(match[1])||match[3]&&!m71Uuid(match[3])||match[5]&&!m71Uuid(match[5]))return respond(404,{error:'Scope 1 record not found.'});const [,company,path,stream,action,id,operation]=match,family:M78Family=path==='process-screen'?'process_screen':'inventory',origin=request.headers.get('origin'),policy=deps.policy??null;if(request.method!=='GET'&&origin!==deps.origin||origin&&origin!==deps.origin)return respond(403,{error:'Forbidden.'});const token=extractBearerToken(request.headers);if(!token)return respond(401,{error:'Authentication required.'});const actor=await deps.validateUser(token);if(!actor)return respond(401,{error:'Authentication required.'});try{if(deps.database.hasStagingAccess&&!await deps.database.hasStagingAccess(actor.id))return respond(403,{error:'Forbidden.'});
 if(request.method!=='GET'&&request.method!=='POST')return respond(405,{error:'Method not allowed.'});if(request.method==='POST'&&!await deps.database.canManageWorkspace(actor.id,company!))return respond(403,{error:'Forbidden.'});let registerPromise:Promise<M78Register|null>|null=null;const root=()=>registerPromise??=deps.database.findScope1(actor.id,company!,deps.authorities,policy),headers={'cache-control':'no-store','x-content-type-options':'nosniff','referrer-policy':'no-referrer'},download=(body:string,type:string,filename:string,extra:Record<string,string>={})=>new Response(body,{headers:{...headers,'content-type':type+'; charset=utf-8','content-disposition':`attachment; filename="${filename}"`,...extra}}),missing=async(kind:'version'|'report')=>{const register=await root();if(!register)return respond(404,{error:'Scope 1 record not found.'});const selected=family==='process_screen'?register.process:register.inventory;if(selected.streamId!==stream)return respond(404,{error:'Scope 1 record not found.'});return respond(404,{error:`Scope 1 ${kind} not found.`})};
 if(request.method==='GET'){if(action==='versions'&&stream&&id){const envelope=await deps.database.findScope1Version(actor.id,company!,stream,id,deps.authorities,policy);if(!envelope||envelope.version.id!==id||envelope.version.companyId!==company||envelope.version.streamId!==stream||envelope.version.family!==family)return await missing('version');if(!operation)return respond(200,envelope);if(operation==='inventory-export')return download(m78CanonicalJson({...envelope.version,review:null}),'application/json','synthetic-scope1-version.json');if(operation==='proof')return respond(200,envelope.proof)}if(action==='reports'&&stream&&id){const report=await deps.database.findScope1Report(actor.id,company!,stream,id,deps.authorities,policy);if(!report||report.id!==id||report.companyId!==company||report.streamId!==stream||report.family!==family)return await missing('report');if(!operation)return respond(200,report);if(operation==='snapshot')return download(report.snapshotJson,'application/json','synthetic-scope1-report-snapshot.json');if(operation==='proof')return respond(200,(parseM78Json(report.snapshotJson)as any).proof);if(operation==='download')return download(report.html,'text/html','synthetic-scope1-report.html',{'content-security-policy':"default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'; sandbox allow-modals"})}const register=await root();if(!register)return respond(404,{error:'Scope 1 record not found.'});const selected=family==='process_screen'?register.process:register.inventory;if(stream&&selected.streamId!==stream)return respond(404,{error:'Scope 1 record not found.'});if(!action)return respond(200,register);if(action==='statements'&&id&&operation==='download'){const s=selected.versions.flatMap(v=>v.statements).find(s=>s.id===id);if(s)return download(s.text,'text/plain','synthetic-scope1-evidence.txt')}return respond(404,{error:'Scope 1 record not found.'})}
 if(id||operation)return respond(405,{error:'Method not allowed.'});const body=parseM78Json(await request.text(),200000);if(action==='reviews'&&stream)return respond(201,await deps.database.reviewScope1Version(actor.id,company!,stream,family,validateM78Review(body),deps.authorities,policy));if(action==='reports'&&stream)return respond(201,await deps.database.createScope1Report(actor.id,company!,stream,family,validateM78Report(body),deps.authorities,policy));if(action&&action!=='versions')return respond(404,{error:'Scope 1 record not found.'});const input=family==='process_screen'?validateM78ProcessSave(body):validateM78InventorySave(body);if(Boolean(stream)!==Boolean(input.expectedVersionId))return respond(422,{error:'Exact correction binding required.'});return respond(201,family==='process_screen'?await deps.database.saveProcessScreen(actor.id,company!,stream??null,input as M78ProcessSaveInput,deps.authorities,policy):await deps.database.saveScope1Inventory(actor.id,company!,stream??null,input as M78InventorySaveInput,deps.authorities,policy));
 }catch(e){if(e instanceof M78ValidationError)return respond(422,{error:e.message});const code=(e as any)?.code;if(code==='M78_STREAM_NOT_FOUND')return respond(404,{error:'Scope 1 record not found.'});if(code==='42501')return respond(403,{error:'Forbidden.'});if(code==='23505')return respond(409,{error:'Scope 1 source, coverage, dependency or request changed. Refresh current records.'});if(['54000','54001'].includes(code))return respond(422,{error:'Scope 1 history capacity reached; retained records remain readable.',code:'history_limit'});if(['22023','22P02','22007','22008','22003'].includes(code))return respond(422,{error:'Invalid or unsupported Scope 1 input.'});return respond(503,{error:'Scope 1 records could not be verified.'})}}}

import { expect, test } from 'bun:test';
import { createHash } from 'node:crypto';
import { readFile } from 'node:fs/promises';
import { pathToFileURL } from 'node:url';

const candidateRoot = 'C:/Users/nimab/.codex/worktrees/m78-get-performance/Neuvetra';
const routePath = `${candidateRoot}/apps/site-api/src/workspace/m78-routes.ts`;
const executableFixturePath = 'evaluations/research-qa/m78-get-route-independent-candidate3-fixture.ts';
const baselinePath = `${candidateRoot}/apps/site-api/src/workspace/m78-get-route-baseline-fixture.ts`;
const originalPath = 'apps/site-api/src/workspace/m78-routes.ts';
const candidateSha256 = 'fd9b1115130d523629e58b5fcef06fe5355eedc8afd12d6dacc998623c89ff37';
const originalSha256 = 'ab5018c64668dfe197755849aee1a2b3c5947f6c3da21e8d18869e998f3f9e01';
const company = '10000000-0000-4000-8000-000000000001';
const otherCompany = '10000000-0000-4000-8000-000000000002';
const actor = '10000000-0000-4000-8000-000000000003';
const origin = 'http://localhost:47821';
const ids = {
  process: { stream: '20000000-0000-4000-8000-000000000001', version: '20000000-0000-4000-8000-000000000002', report: '20000000-0000-4000-8000-000000000003' },
  inventory: { stream: '30000000-0000-4000-8000-000000000001', version: '30000000-0000-4000-8000-000000000002', report: '30000000-0000-4000-8000-000000000003' },
} as const;

const sha = (bytes: Uint8Array) => createHash('sha256').update(bytes).digest('hex');
const row = (family: 'process_screen' | 'inventory') => {
  const id = ids[family === 'process_screen' ? 'process' : 'inventory'];
  const version = { id: id.version, companyId: company, streamId: id.stream, family, statements: [], activity: {}, versionSha256: 'a'.repeat(64) };
  return {
    id,
    envelope: { version, proof: { family } },
    report: { id: id.report, companyId: company, streamId: id.stream, family, versionId: id.version, snapshotJson: JSON.stringify({ proof: { family } }), html: `<p>${family}</p>` },
  };
};
const register = () => {
  const process = row('process_screen');
  const inventory = row('inventory');
  return {
    process: { streamId: process.id.stream, versions: [process.envelope.version], reports: [process.report] },
    inventory: { streamId: inventory.id.stream, versions: [inventory.envelope.version], reports: [inventory.report] },
  };
};

type Counts = { root: number; version: number; report: number; writes: number };
const database = (overrides: Record<string, unknown> = {}) => {
  const counts: Counts = { root: 0, version: 0, report: 0, writes: 0 };
  const db = {
    hasStagingAccess: async () => true,
    canManageWorkspace: async () => true,
    findScope1: async () => { counts.root++; return register(); },
    findScope1Version: async (_u: string, _c: string, stream: string, id: string) => {
      counts.version++;
      for (const family of ['process_screen', 'inventory'] as const) {
        const value = row(family);
        if (value.id.stream === stream && value.id.version === id) return value.envelope;
      }
      return null;
    },
    findScope1Report: async (_u: string, _c: string, stream: string, id: string) => {
      counts.report++;
      for (const family of ['process_screen', 'inventory'] as const) {
        const value = row(family);
        if (value.id.stream === stream && value.id.report === id) return value.report;
      }
      return null;
    },
    saveProcessScreen: async () => { counts.writes++; return row('process_screen').envelope; },
    saveScope1Inventory: async () => { counts.writes++; return row('inventory').envelope; },
    reviewScope1Version: async () => { counts.writes++; return {}; },
    createScope1Report: async () => { counts.writes++; return row('inventory').report; },
    ...overrides,
  };
  return { counts, db };
};

const loadFactory = async () => {
  const bytes = await readFile(routePath);
  expect(sha(bytes)).toBe(candidateSha256);
  return (await import(pathToFileURL(executableFixturePath).href)).createM78Routes as (deps: any) => (request: Request) => Promise<Response>;
};
const makeRoute = async (db: any, staging = true) => (await loadFactory())({
  database: { ...db, hasStagingAccess: async () => staging },
  origin,
  authorities: {},
  policy: null,
  validateUser: async (token: string) => token === 'valid' ? { id: actor, email: null, phone: null, fullName: null } : null,
});
const call = (route: (request: Request) => Promise<Response>, path: string, token = 'valid') => route(new Request(`${origin}/workspace/${company}/${path}`, { headers: { authorization: `Bearer ${token}`, origin } }));

test('baseline fixture is the exact historical route under documented symbol transformation and POST tail is unchanged', async () => {
  const originalBytes = await readFile(originalPath);
  const candidateBytes = await readFile(routePath);
  const baselineBytes = await readFile(baselinePath);
  const executableFixture = await readFile(executableFixturePath, 'utf8');
  expect(sha(originalBytes)).toBe(originalSha256);
  expect(sha(candidateBytes)).toBe(candidateSha256);
  expect(sha(baselineBytes)).toBe('8ebe51aec86d8e5990a6f8391bb8e823c7cd661d2d7369e3b35909ef74722de3');
  const original = originalBytes.toString('utf8');
  const candidate = candidateBytes.toString('utf8');
  const reconstructed = baselineBytes.toString('utf8').replace(/^\/\*\* Frozen baseline route fixture[^\n]*\n/, '').replace('createM78RoutesBaseline', 'createM78Routes');
  expect(reconstructed).toBe(original);
  const recoveredCandidate = executableFixture
    .replace(/^\/\*\* QA import-path adaptation[^\n]*\n/, '')
    .replaceAll('../../packages/', '../../../../packages/')
    .replace("'../../apps/site-api/src/lib/auth'", "'../lib/auth'");
  expect(recoveredCandidate).toBe(candidate);
  const start = " if(request.method!=='GET'&&request.method!=='POST')";
  const originalStart = original.indexOf(start);
  const candidateStart = candidate.indexOf(start);
  expect(original.slice(0, originalStart)).toBe(candidate.slice(0, candidateStart));
  const originalPost = original.indexOf(' if(id||operation)return respond(405', originalStart);
  const candidatePost = candidate.indexOf(' if(id||operation)return respond(405', candidateStart);
  expect(original.slice(originalPost)).toBe(candidate.slice(candidatePost));
});

test('valid direct version and report reads use one specific getter and no root or writer', async () => {
  for (const family of ['process_screen', 'inventory'] as const) {
    const value = row(family);
    const prefix = family === 'process_screen' ? 'process-screen' : 'scope1-inventory';
    const fixture = database();
    const route = await makeRoute(fixture.db);
    const version = await call(route, `${prefix}/${value.id.stream}/versions/${value.id.version}`);
    const report = await call(route, `${prefix}/${value.id.stream}/reports/${value.id.report}`);
    expect(version.status).toBe(200);
    expect(await version.json()).toEqual(value.envelope);
    expect(report.status).toBe(200);
    expect(await report.json()).toEqual(value.report);
    expect(fixture.counts).toEqual({ root: 0, version: 1, report: 1, writes: 0 });
  }
});

test('every mismatched returned identity falls back and releases no direct bytes', async () => {
  const good = row('inventory');
  for (const [kind, mutate] of [
    ['version', (value: any) => { value.version.id = ids.process.version; }],
    ['version', (value: any) => { value.version.companyId = otherCompany; }],
    ['version', (value: any) => { value.version.streamId = ids.process.stream; }],
    ['version', (value: any) => { value.version.family = 'process_screen'; }],
    ['report', (value: any) => { value.id = ids.process.report; }],
    ['report', (value: any) => { value.companyId = otherCompany; }],
    ['report', (value: any) => { value.streamId = ids.process.stream; }],
    ['report', (value: any) => { value.family = 'process_screen'; }],
  ] as const) {
    const value: any = structuredClone(kind === 'version' ? good.envelope : good.report);
    mutate(value);
    const fixture = database(kind === 'version'
      ? { findScope1Version: async () => { fixture.counts.version++; return value; } }
      : { findScope1Report: async () => { fixture.counts.report++; return value; } });
    const route = await makeRoute(fixture.db);
    const id = kind === 'version' ? good.id.version : good.id.report;
    const response = await call(route, `scope1-inventory/${good.id.stream}/${kind}s/${id}`);
    expect(response.status).toBe(404);
    expect(await response.json()).toEqual({ error: `Scope 1 ${kind} not found.` });
    expect(fixture.counts.root).toBe(1);
    expect(fixture.counts.writes).toBe(0);
  }
});

test('actual cross-family request keeps generic 404 and asynchronous fallback errors remain mapped', async () => {
  const process = row('process_screen');
  for (const [kind, id] of [['version', process.id.version], ['report', process.id.report]] as const) {
    const fixture = database();
    const route = await makeRoute(fixture.db);
    const response = await call(route, `scope1-inventory/${process.id.stream}/${kind}s/${id}`);
    expect(response.status).toBe(404);
    expect(await response.json()).toEqual({ error: 'Scope 1 record not found.' });
    expect(fixture.counts.root).toBe(1);
  }
  for (const [error, status, body] of [
    [Object.assign(Error('denied'), { code: '42501' }), 403, { error: 'Forbidden.' }],
    [Object.assign(Error('capacity'), { code: '54000' }), 422, { error: 'Scope 1 history capacity reached; retained records remain readable.', code: 'history_limit' }],
    [Object.assign(Error('invalid'), { code: '22023' }), 422, { error: 'Invalid or unsupported Scope 1 input.' }],
    [Error('corrupt'), 503, { error: 'Scope 1 records could not be verified.' }],
  ] as const) {
    const fixture = database({
      findScope1Report: async () => { fixture.counts.report++; return null; },
      findScope1: async () => { fixture.counts.root++; await Promise.resolve(); throw error; },
    });
    const route = await makeRoute(fixture.db);
    const response = await call(route, `scope1-inventory/${ids.inventory.stream}/reports/${ids.inventory.report}`);
    expect(response.status).toBe(status);
    expect(await response.json()).toEqual(body);
    expect(fixture.counts).toEqual({ root: 1, version: 0, report: 1, writes: 0 });
  }
});

test('authentication and staging refusals occur before direct or root getters', async () => {
  const fixture = database();
  const route = await makeRoute(fixture.db);
  const path = `scope1-inventory/${ids.inventory.stream}/reports/${ids.inventory.report}`;
  expect((await call(route, path, 'invalid')).status).toBe(401);
  const staged = await makeRoute(fixture.db, false);
  expect((await call(staged, path)).status).toBe(403);
  expect(fixture.counts).toEqual({ root: 0, version: 0, report: 0, writes: 0 });
});
